  2	const Allocator = std.mem.Allocator;
  3	
  4	const apprt = @import("../apprt.zig");
  5	const build_config = @import("../build_config.zig");
  6	const App = @import("../App.zig");
  7	const Surface = @import("../Surface.zig");
  8	const renderer = @import("../renderer.zig");
  9	const terminal = @import("../terminal/main.zig");
 10	const Config = @import("../config.zig").Config;
 11	const MessageData = @import("../datastruct/main.zig").MessageData;
 12	
 13	/// The message types that can be sent to a single surface.
 14	pub const Message = union(enum) {
 15	    /// Represents a write request. Magic number comes from the max size
 16	    /// we want this union to be.
 17	    pub const WriteReq = MessageData(u8, 255);
 18	
 19	    /// A fixed-size desktop notification payload sent to the app thread.
 20	    pub const DesktopNotification = struct {
 21	        /// Desktop notification title.
 22	        title: [63:0]u8,
 23	
 24	        /// Desktop notification body.
 25	        body: [255:0]u8,
 26	
 27	        pub fn init(title: []const u8, body: []const u8) DesktopNotification {
 28	            var result: DesktopNotification = undefined;
 29	            copyUtf8Z(result.title.len, &result.title, title);
 30	            copyUtf8Z(result.body.len, &result.body, body);
 31	            return result;
 32	        }
 33	
 34	        /// UTF-8 continuation bytes occupy the range 0x80 through 0xBF.
 35	        fn isUtf8ContinuationByte(byte: u8) bool {
 36	            return switch (byte) {
 37	                0x80...0xBF => true,
 38	                else => false,
 39	            };
 40	        }
 41	
 42	        /// Copy as much of `src` as fits, backing up from a UTF-8 continuation
 43	        /// byte so valid input is never truncated in the middle of a codepoint.
 44	        fn copyUtf8Z(
 45	            comptime capacity: usize,
 46	            dst: *[capacity:0]u8,
 47	            src: []const u8,
 48	        ) void {
 49	            var len = @min(src.len, capacity);
 50	            while (len > 0 and
 51	                len < src.len and
 52	                isUtf8ContinuationByte(src[len])) : (len -= 1)
 53	            {}
 54	
 55	            @memcpy(dst[0..len], src[0..len]);
 56	            dst[len] = 0;
 57	        }
 58	    };
 59	
 60	    /// Set the title of the surface.
 61	    /// TODO: we should change this to a "WriteReq" style structure in
 62	    /// the termio message so that we can more efficiently send strings
 63	    /// of any length
 64	    set_title: [256]u8,
 65	
 66	    /// Report the window title back to the terminal
 67	    report_title: ReportTitleStyle,
 68	
 69	    /// Resize the window to the given grid size, as requested by the
 70	    /// running program (CSI 8 t).
 71	    resize_window: terminal.StreamAction.ResizeWindow,
 72	
 73	    /// Set the mouse shape.
 74	    set_mouse_shape: terminal.MouseShape,
 75	
 76	    /// Read the clipboard and write to the pty.
 77	    clipboard_read: apprt.Clipboard,
 78	
 79	    /// A Kitty clipboard protocol (OSC 5522) read request. The receiver
 80	    /// takes ownership of the request state and must eventually destroy
 81	    /// it.
 82	    kitty_clipboard_read: *apprt.ClipboardRequest.KittyRead,
 83	
 84	    /// A committed Kitty clipboard protocol (OSC 5522) write
 85	    /// transaction. The receiver takes ownership of the request state
 86	    /// and must eventually destroy it.
 87	    kitty_clipboard_write: *apprt.ClipboardRequest.KittyWrite,
 88	
 89	    /// Write the clipboard contents.
 90	    clipboard_write: struct {
 91	        clipboard_type: apprt.Clipboard,
 92	        req: WriteReq,
 93	    },
 94	
 95	    /// Change the configuration to the given configuration. The pointer is
 96	    /// not valid after receiving this message so any config must be used
 97	    /// and derived immediately.
 98	    change_config: *const Config,
 99	
100	    /// Close the surface. This will only close the current surface that
101	    /// receives this, not the full application.
102	    close: void,
103	
104	    /// The child process running in the surface has exited. This may trigger
105	    /// a surface close, it may not. Additional details about the child
106	    /// command are given in the `ChildExited` struct.
107	    child_exited: ChildExited,
108	
109	    /// Show a desktop notification.
110	    desktop_notification: DesktopNotification,
111	
112	    /// Health status change for the renderer.
113	    renderer_health: renderer.Health,
114	
115	    /// Tell the surface to present itself to the user. This may require raising
116	    /// a window and switching tabs.
117	    present_surface: void,
118	
119	    /// Notifies the surface that password input has started within
120	    /// the terminal. This should always be followed by a false value
121	    /// unless the surface exits.
122	    password_input: bool,
123	
124	    /// A terminal color was changed using OSC sequences.
125	    color_change: terminal.osc.color.ColoredTarget,
126	
127	    /// Notifies the surface that a tick of the timer that is timing
128	    /// out selection scrolling has occurred. "selection scrolling"
129	    /// is when the user has clicked and dragged the mouse outside
130	    /// the viewport of the terminal and the terminal is scrolling
131	    /// the viewport to follow the mouse cursor.
132	    selection_scroll_tick: bool,
133	
134	    /// The terminal has reported a change in the working directory.
135	    pwd_change: WriteReq,
136	
137	    /// The terminal encountered a bell character.
138	    ring_bell,
139	
140	    /// Report the progress of an action using a GUI element
141	    progress_report: terminal.osc.Command.ProgressReport,
142	
143	    /// A command has started in the shell, start a timer.
144	    start_command,
145	
146	    /// A command has finished in the shell, stop the timer and send out
147	    /// notifications as appropriate. The optional u8 is the exit code
148	    /// of the command.
149	    stop_command: ?u8,
150	
151	    /// The scrollbar state changed for the surface.
152	    scrollbar: terminal.Scrollbar,
153	
154	    /// Search progress update
155	    search_total: ?usize,
156	
157	    /// Selected search index change
158	    search_selected: ?usize,
159	
160	    /// Renderer pushed a new frame, redraw this surface.
161	    redraw,
162	
163	    pub const ReportTitleStyle = enum {
164	        csi_21_t,
165	
166	        // This enum is a placeholder for future title styles.
167	    };
168	
169	    pub const ChildExited = extern struct {
170	        exit_code: u32,
171	        runtime_ms: u64,
172	
173	        /// Make this a valid gobject if we're in a GTK environment.
174	        pub const getGObjectType = switch (build_config.app_runtime) {
175	            .gtk,
176	            => @import("gobject").ext.defineBoxed(
177	                ChildExited,
178	                .{ .name = "GhosttyApprtChildExited" },
179	            ),
180	
181	            .none => void,
182	        };
183	    };
184	};
