209	/// Context for new surface creation to determine inheritance behavior
210	pub const NewSurfaceContext = enum(c_int) {
211	    window = 0,
212	    tab = 1,
213	    split = 2,
214	};
215	
216	pub fn shouldInheritWorkingDirectory(context: NewSurfaceContext, config: *const Config) bool {
217	    return switch (context) {
218	        .window => config.@"window-inherit-working-directory",
219	        .tab => config.@"tab-inherit-working-directory",
220	        .split => config.@"split-inherit-working-directory",
221	    };
222	}
223	
224	/// Returns a new config for a surface for the given app that should be
225	/// used for any new surfaces. The resulting config should be deinitialized
226	/// after the surface is initialized.
227	pub fn newConfig(
228	    app: *const App,
229	    config: *const Config,
230	    context: NewSurfaceContext,
231	) Allocator.Error!Config {
232	    // Create a shallow clone
233	    var copy = config.shallowClone(app.alloc);
234	
235	    // Our allocator is our config's arena
236	    const alloc = copy._arena.?.allocator();
237	
238	    // Get our previously focused surface for some inherited values.
239	    const prev = app.focusedSurface();
240	    if (prev) |p| {
241	        if (shouldInheritWorkingDirectory(context, config)) {
242	            if (try p.pwd(alloc)) |pwd| {
243	                copy.@"working-directory" = .{ .path = pwd };
244	            }
245	        }
246	    }
247	
248	    return copy;
249	}
