258	test "copyUtf8Z handles len at the final byte of every UTF-8 sequence length" {
259	    const DesktopNotification = Message.DesktopNotification;
260	
261	    var dst_1_byte: [1:0]u8 = undefined;
262	    const src_ending_in_1_byte_codepoint = "ab";
263	    try std.testing.expect(!DesktopNotification.isUtf8ContinuationByte(
264	        src_ending_in_1_byte_codepoint[dst_1_byte.len],
265	    ));
266	    DesktopNotification.copyUtf8Z(
267	        dst_1_byte.len,
268	        &dst_1_byte,
269	        src_ending_in_1_byte_codepoint,
270	    );
271	    try std.testing.expectEqualStrings("a", std.mem.sliceTo(&dst_1_byte, 0));
272	
273	    var dst_2_bytes: [2:0]u8 = undefined;
274	    const src_ending_in_2_byte_codepoint = "aЯ";
275	    try std.testing.expect(DesktopNotification.isUtf8ContinuationByte(
276	        src_ending_in_2_byte_codepoint[dst_2_bytes.len],
277	    ));
278	    DesktopNotification.copyUtf8Z(
279	        dst_2_bytes.len,
280	        &dst_2_bytes,
281	        src_ending_in_2_byte_codepoint,
282	    );
283	    try std.testing.expectEqualStrings("a", std.mem.sliceTo(&dst_2_bytes, 0));
284	
285	    var dst_3_bytes: [3:0]u8 = undefined;
286	    const src_ending_in_3_byte_codepoint = "a€";
287	    try std.testing.expect(DesktopNotification.isUtf8ContinuationByte(
288	        src_ending_in_3_byte_codepoint[dst_3_bytes.len],
289	    ));
290	    DesktopNotification.copyUtf8Z(
291	        dst_3_bytes.len,
292	        &dst_3_bytes,
293	        src_ending_in_3_byte_codepoint,
294	    );
295	    try std.testing.expectEqualStrings("a", std.mem.sliceTo(&dst_3_bytes, 0));
296	
297	    var dst_4_bytes: [4:0]u8 = undefined;
