   663	    fn quitNow(self: *Self) void {
   664	        // Get all our windows and destroy them, forcing them to free.
   665	        const list = gtk.Window.listToplevels();
   666	        defer list.free();
   667	        list.foreach(struct {
   668	            fn callback(data: ?*anyopaque, _: ?*anyopaque) callconv(.c) void {
   669	                const ptr = data orelse return;
   670	                const window: *gtk.Window = @ptrCast(@alignCast(ptr));
   671	
   672	                // We only want to destroy our windows. These windows own
   673	                // every other type of window that is possible so this will
   674	                // trigger a proper shutdown sequence.
   675	                //
   676	                // We previously just destroyed ALL windows but this leads to
   677	                // a double-free with the fcitx ime, because it has a nested
   678	                // gtk.Window as a property that we don't own and it later
   679	                // tries to free on its own. I think this is probably a bug in
   680	                // the fcitx ime widget but still, we don't want a double free!
   681	                if (gobject.ext.isA(window, Window)) {
   682	                    window.destroy();
   683	                }
   684	            }
   685	        }.callback, null);
